-- old-writers: refuse
-- applied-by: goh state contract
CREATE TABLE refuse_lands(what TEXT NOT NULL, n INTEGER NOT NULL CHECK (n = 0)) STRICT;
INSERT INTO refuse_lands SELECT 'a row with a document, no fill, or a field left in rest', count(*) FROM lands WHERE body <> '{}' OR rest IS NULL OR json_type(rest, '$.at') IS NOT NULL OR json_type(rest, '$.attempt') IS NOT NULL OR json_type(rest, '$.batch.gates') IS NOT NULL OR json_type(rest, '$.batch.id') IS NOT NULL OR json_type(rest, '$.batch.items') IS NOT NULL OR json_type(rest, '$.cap_items') IS NOT NULL OR json_type(rest, '$.cause') IS NOT NULL OR json_type(rest, '$.cause_detail') IS NOT NULL OR json_type(rest, '$.cov_risk.base') IS NOT NULL OR json_type(rest, '$.cov_risk.carry') IS NOT NULL OR json_type(rest, '$.cov_risk.files') IS NOT NULL OR json_type(rest, '$.cov_risk.head') IS NOT NULL OR json_type(rest, '$.cov_risk.lines') IS NOT NULL OR json_type(rest, '$.cov_risk.said') IS NOT NULL OR json_type(rest, '$.diffcov_item.id') IS NOT NULL OR json_type(rest, '$.diffcov_item.said') IS NOT NULL OR json_type(rest, '$.early') IS NOT NULL OR json_type(rest, '$.enqueued') IS NOT NULL OR json_type(rest, '$.finished') IS NOT NULL OR json_type(rest, '$.flakes') IS NOT NULL OR json_type(rest, '$.guard') IS NOT NULL OR json_type(rest, '$.guards') IS NOT NULL OR json_type(rest, '$.item') IS NOT NULL OR json_type(rest, '$.k') IS NOT NULL OR json_type(rest, '$.k_why') IS NOT NULL OR json_type(rest, '$.landed') IS NOT NULL OR json_type(rest, '$.load_end') IS NOT NULL OR json_type(rest, '$.load_start') IS NOT NULL OR json_type(rest, '$.log') IS NOT NULL OR json_type(rest, '$.mode') IS NOT NULL OR json_type(rest, '$.pre_affected.by') IS NOT NULL OR json_type(rest, '$.pre_affected.lane_s') IS NOT NULL OR json_type(rest, '$.pre_affected.ran') IS NOT NULL OR json_type(rest, '$.pre_affected.tests') IS NOT NULL OR json_type(rest, '$.pre_affected.took') IS NOT NULL OR json_type(rest, '$.pre_run.cpu_s') IS NOT NULL OR json_type(rest, '$.pre_run.limit_s') IS NOT NULL OR json_type(rest, '$.pre_run.remote.cause') IS NOT NULL OR json_type(rest, '$.pre_run.remote.fresh') IS NOT NULL OR json_type(rest, '$.pre_run.remote.host') IS NOT NULL OR json_type(rest, '$.pre_run.remote.mac_est_s') IS NOT NULL OR json_type(rest, '$.pre_run.remote.mac_s') IS NOT NULL OR json_type(rest, '$.pre_run.remote.outcome') IS NOT NULL OR json_type(rest, '$.pre_run.remote.rerun_s') IS NOT NULL OR json_type(rest, '$.pre_run.remote.saved_s') IS NOT NULL OR json_type(rest, '$.pre_run.remote.t0') IS NOT NULL OR json_type(rest, '$.pre_run.remote.tests') IS NOT NULL OR json_type(rest, '$.pre_run.remote.where') IS NOT NULL OR json_type(rest, '$.pre_run.remote.worker_s') IS NOT NULL OR json_type(rest, '$.pre_run.run_s') IS NOT NULL OR json_type(rest, '$.pre_run.skipped') IS NOT NULL OR json_type(rest, '$.pre_run.wait_s') IS NOT NULL OR json_type(rest, '$.pre_run.workers') IS NOT NULL OR json_type(rest, '$.pre_s') IS NOT NULL OR json_type(rest, '$.recorded') IS NOT NULL OR json_type(rest, '$.red_cause.cause') IS NOT NULL OR json_type(rest, '$.red_cause.rule') IS NOT NULL OR json_type(rest, '$.red_cause.tests') IS NOT NULL OR json_type(rest, '$.red_logs') IS NOT NULL OR json_type(rest, '$.remote_shares') IS NOT NULL OR json_type(rest, '$.repo') IS NOT NULL OR json_type(rest, '$.requested') IS NOT NULL OR json_type(rest, '$.sha') IS NOT NULL OR json_type(rest, '$.slot_s') IS NOT NULL OR json_type(rest, '$.slot_wait_by_class.land') IS NOT NULL OR json_type(rest, '$.slot_wait_by_class.pre') IS NOT NULL OR json_type(rest, '$.slot_wait_by_class.short') IS NOT NULL OR json_type(rest, '$.slot_wait_by_class.work') IS NOT NULL OR json_type(rest, '$.slot_wait_s') IS NOT NULL OR json_type(rest, '$.stage') IS NOT NULL OR json_type(rest, '$.started') IS NOT NULL OR json_type(rest, '$.state') IS NOT NULL OR json_type(rest, '$.waived') IS NOT NULL OR json_type(rest, '$.why') IS NOT NULL;
INSERT INTO refuse_lands SELECT 'a red cause not folded', count(*) FROM red_causes r JOIN lands l ON l.queue = r.queue AND l.run = r.run WHERE l.red_class IS NULL;
INSERT INTO refuse_lands SELECT 'a guard whose red land lists none', count(*) FROM land_guards g WHERE NOT EXISTS (SELECT 1 FROM lands l JOIN land_lists c ON c.queue = l.queue AND c.run = l.run AND c.kind = 'guard' WHERE l.queue = g.queue AND l.sha IS g.body ->> '$.sha' AND l.item IS g.body ->> '$.item' AND l.state = 'red');
DROP TABLE red_causes;
DROP TABLE land_guards;
DROP TABLE refuse_lands;
DROP TRIGGER lands_fill;
DROP TRIGGER lands_refill;
DROP TRIGGER lands_bad;
DROP VIEW lands_v1;
ALTER TABLE lands DROP COLUMN body;
CREATE VIEW lands_v1 AS SELECT run, item, sha, enqueued, repo, mode, state, attempt, requested, started, finished, k, at,
  json_patch(json_patch('{}', json_object('item', lands.item, 'sha', lands.sha, 'enqueued', lands.enqueued, 'repo', lands.repo, 'mode', lands.mode, 'state', lands.state, 'attempt', lands.attempt, 'requested', lands.requested, 'started', lands.started, 'finished', lands.finished, 'k', lands.k, 'landed', lands.landed, 'log', lands.log, 'why', lands.why, 'stage', lands.stage, 'cause', lands.cause, 'cause_detail', lands.cause_detail, 'k_why', lands.k_why, 'pre_affected', CASE WHEN coalesce(lands.pre_affected_ran, lands.pre_affected_took, lands.pre_affected_by, lands.pre_affected_lane_s, lands.pre_affected_tests) IS NOT NULL THEN json_object('ran', lands.pre_affected_ran, 'took', lands.pre_affected_took, 'by', lands.pre_affected_by, 'lane_s', lands.pre_affected_lane_s, 'tests', lands.pre_affected_tests) END, 'batch', CASE WHEN coalesce(lands.batch, lands.batch_items, lands.batch_gates) IS NOT NULL THEN json_object('id', lands.batch, 'items', lands.batch_items, 'gates', lands.batch_gates) END, 'pre_run', CASE WHEN coalesce(lands.pre_run_skipped, coalesce(lands.remote_outcome, lands.remote_cause, lands.remote_where, lands.remote_host, lands.remote_worker_s, lands.remote_mac_s, lands.remote_mac_est_s, lands.remote_rerun_s, lands.remote_saved_s, lands.remote_t0, lands.remote_tests, lands.remote_fresh), lands.pre_run_wait_s, lands.pre_run_run_s, lands.pre_run_limit_s, lands.pre_run_cpu_s, lands.pre_run_workers) IS NOT NULL THEN json_object('skipped', lands.pre_run_skipped, 'remote', CASE WHEN coalesce(lands.remote_outcome, lands.remote_cause, lands.remote_where, lands.remote_host, lands.remote_worker_s, lands.remote_mac_s, lands.remote_mac_est_s, lands.remote_rerun_s, lands.remote_saved_s, lands.remote_t0, lands.remote_tests, lands.remote_fresh) IS NOT NULL THEN json_object('outcome', lands.remote_outcome, 'cause', lands.remote_cause, 'where', lands.remote_where, 'host', lands.remote_host, 'worker_s', lands.remote_worker_s, 'mac_s', lands.remote_mac_s, 'mac_est_s', lands.remote_mac_est_s, 'rerun_s', lands.remote_rerun_s, 'saved_s', lands.remote_saved_s, 't0', lands.remote_t0, 'tests', lands.remote_tests, 'fresh', CASE lands.remote_fresh WHEN 1 THEN json('true') WHEN 0 THEN json('false') END) END, 'wait_s', lands.pre_run_wait_s, 'run_s', lands.pre_run_run_s, 'limit_s', lands.pre_run_limit_s, 'cpu_s', lands.pre_run_cpu_s, 'workers', lands.pre_run_workers) END, 'red_cause', CASE WHEN coalesce(lands.red_class, lands.red_rule, (SELECT 1 FROM land_lists c WHERE c.queue = lands.queue AND c.run = lands.run AND c.kind = 'red_test' LIMIT 1)) IS NOT NULL THEN json_object('cause', lands.red_class, 'rule', lands.red_rule, 'tests', json(nullif(nullif((SELECT json_group_array(c.value ORDER BY c.ord) FROM land_lists c WHERE c.queue = lands.queue AND c.run = lands.run AND c.kind = 'red_test'), '[]'), '{}'))) END, 'diffcov_item', CASE WHEN coalesce(lands.diffcov_item, lands.diffcov_said) IS NOT NULL THEN json_object('id', lands.diffcov_item, 'said', lands.diffcov_said) END, 'cov_risk', CASE WHEN coalesce(lands.cov_said, lands.cov_head, lands.cov_base, lands.cov_lines, (SELECT 1 FROM land_cov_carry c WHERE c.queue = lands.queue AND c.run = lands.run LIMIT 1), (SELECT 1 FROM land_cov_files c WHERE c.queue = lands.queue AND c.run = lands.run LIMIT 1)) IS NOT NULL THEN json_object('said', lands.cov_said, 'head', lands.cov_head, 'base', lands.cov_base, 'lines', lands.cov_lines, 'carry', json(nullif(nullif((SELECT json_group_array(json_patch('{}', json_object('file', c.file, 'text', c.text, 'why', c.why, 'line', c.line, 'own', CASE c.own WHEN 1 THEN json('true') WHEN 0 THEN json('false') END, 'measured', CASE c.measured WHEN 1 THEN json('true') WHEN 0 THEN json('false') END)) ORDER BY c.ord) FROM land_cov_carry c WHERE c.queue = lands.queue AND c.run = lands.run), '[]'), '{}')), 'files', json(nullif(nullif((SELECT json_group_object(c.path, c.said) FROM land_cov_files c WHERE c.queue = lands.queue AND c.run = lands.run), '[]'), '{}'))) END, 'pre_s', lands.pre_s, 'slot_s', lands.slot_s, 'slot_wait_s', lands.slot_wait_s, 'load_start', lands.load_start, 'load_end', lands.load_end, 'slot_wait_by_class', CASE WHEN coalesce(lands.slot_wait_short_s, lands.slot_wait_land_s, lands.slot_wait_pre_s, lands.slot_wait_work_s) IS NOT NULL THEN json_object('short', lands.slot_wait_short_s, 'land', lands.slot_wait_land_s, 'pre', lands.slot_wait_pre_s, 'work', lands.slot_wait_work_s) END, 'early', CASE lands.early WHEN 1 THEN json('true') WHEN 0 THEN json('false') END, 'recorded', CASE lands.recorded WHEN 1 THEN json('true') WHEN 0 THEN json('false') END, 'guards', json(nullif(nullif((SELECT json_group_array(c.value ORDER BY c.ord) FROM land_lists c WHERE c.queue = lands.queue AND c.run = lands.run AND c.kind = 'guard'), '[]'), '{}')), 'red_logs', json(nullif(nullif((SELECT json_group_array(c.value ORDER BY c.ord) FROM land_lists c WHERE c.queue = lands.queue AND c.run = lands.run AND c.kind = 'red_log'), '[]'), '{}')), 'flakes', json(nullif(nullif((SELECT json_group_array(json_patch('{}', json_object('test', c.test, 'entry', c.entry, 'filed', c.filed)) ORDER BY c.ord) FROM land_flakes c WHERE c.queue = lands.queue AND c.run = lands.run), '[]'), '{}')), 'remote_shares', json(nullif(nullif((SELECT json_group_array(json_patch('{}', json_object('host', c.host, 'outcome', c.outcome, 'where', c.place, 'mac_est_s', c.mac_est_s, 'mac_s', c.mac_s, 'rerun_s', c.rerun_s, 'saved_s', c.saved_s, 't0', c.t0, 'worker_s', c.worker_s, 'tests', c.tests)) ORDER BY c.ord) FROM land_remote_shares c WHERE c.queue = lands.queue AND c.run = lands.run), '[]'), '{}')), 'cap_items', json(nullif(nullif((SELECT json_group_array(json_patch('{}', json_object('id', c.id, 'file', c.file, 'said', c.said, 'lines', c.lines)) ORDER BY c.ord) FROM land_cap_items c WHERE c.queue = lands.queue AND c.run = lands.run), '[]'), '{}')), 'waived', json(nullif(nullif((SELECT json_group_array(json_patch('{}', json_object('node', c.node, 'kind', c.kind, 'rule', c.rule, 'commit', c.commit_sha, 'sha', c.sha, 'reason', c.reason, 'reading', c.reading, 'items', json(nullif((SELECT json_group_array(i.value ORDER BY i.i) FROM land_waived_items i WHERE i.queue = c.queue AND i.run = c.run AND i.ord = c.ord), '[]')))) ORDER BY c.ord) FROM land_waived c WHERE c.queue = lands.queue AND c.run = lands.run), '[]'), '{}')), 'guard', (SELECT value FROM land_lists c WHERE c.queue=lands.queue AND c.run=lands.run AND c.kind='guard' AND c.ord=0), 'at', strftime('%Y-%m-%dT%H:%M:%SZ', lands.at, 'unixepoch'))), coalesce(lands.rest, '{}')) AS body FROM lands;
CREATE TRIGGER lands_rest_insert BEFORE INSERT ON lands WHEN json_type(NEW.rest, '$.at') IS NOT NULL OR json_type(NEW.rest, '$.attempt') IS NOT NULL OR json_type(NEW.rest, '$.batch.gates') IS NOT NULL OR json_type(NEW.rest, '$.batch.id') IS NOT NULL OR json_type(NEW.rest, '$.batch.items') IS NOT NULL OR json_type(NEW.rest, '$.cap_items') IS NOT NULL OR json_type(NEW.rest, '$.cause') IS NOT NULL OR json_type(NEW.rest, '$.cause_detail') IS NOT NULL OR json_type(NEW.rest, '$.cov_risk.base') IS NOT NULL OR json_type(NEW.rest, '$.cov_risk.carry') IS NOT NULL OR json_type(NEW.rest, '$.cov_risk.files') IS NOT NULL OR json_type(NEW.rest, '$.cov_risk.head') IS NOT NULL OR json_type(NEW.rest, '$.cov_risk.lines') IS NOT NULL OR json_type(NEW.rest, '$.cov_risk.said') IS NOT NULL OR json_type(NEW.rest, '$.diffcov_item.id') IS NOT NULL OR json_type(NEW.rest, '$.diffcov_item.said') IS NOT NULL OR json_type(NEW.rest, '$.early') IS NOT NULL OR json_type(NEW.rest, '$.enqueued') IS NOT NULL OR json_type(NEW.rest, '$.finished') IS NOT NULL OR json_type(NEW.rest, '$.flakes') IS NOT NULL OR json_type(NEW.rest, '$.guard') IS NOT NULL OR json_type(NEW.rest, '$.guards') IS NOT NULL OR json_type(NEW.rest, '$.item') IS NOT NULL OR json_type(NEW.rest, '$.k') IS NOT NULL OR json_type(NEW.rest, '$.k_why') IS NOT NULL OR json_type(NEW.rest, '$.landed') IS NOT NULL OR json_type(NEW.rest, '$.load_end') IS NOT NULL OR json_type(NEW.rest, '$.load_start') IS NOT NULL OR json_type(NEW.rest, '$.log') IS NOT NULL OR json_type(NEW.rest, '$.mode') IS NOT NULL OR json_type(NEW.rest, '$.pre_affected.by') IS NOT NULL OR json_type(NEW.rest, '$.pre_affected.lane_s') IS NOT NULL OR json_type(NEW.rest, '$.pre_affected.ran') IS NOT NULL OR json_type(NEW.rest, '$.pre_affected.tests') IS NOT NULL OR json_type(NEW.rest, '$.pre_affected.took') IS NOT NULL OR json_type(NEW.rest, '$.pre_run.cpu_s') IS NOT NULL OR json_type(NEW.rest, '$.pre_run.limit_s') IS NOT NULL OR json_type(NEW.rest, '$.pre_run.remote.cause') IS NOT NULL OR json_type(NEW.rest, '$.pre_run.remote.fresh') IS NOT NULL OR json_type(NEW.rest, '$.pre_run.remote.host') IS NOT NULL OR json_type(NEW.rest, '$.pre_run.remote.mac_est_s') IS NOT NULL OR json_type(NEW.rest, '$.pre_run.remote.mac_s') IS NOT NULL OR json_type(NEW.rest, '$.pre_run.remote.outcome') IS NOT NULL OR json_type(NEW.rest, '$.pre_run.remote.rerun_s') IS NOT NULL OR json_type(NEW.rest, '$.pre_run.remote.saved_s') IS NOT NULL OR json_type(NEW.rest, '$.pre_run.remote.t0') IS NOT NULL OR json_type(NEW.rest, '$.pre_run.remote.tests') IS NOT NULL OR json_type(NEW.rest, '$.pre_run.remote.where') IS NOT NULL OR json_type(NEW.rest, '$.pre_run.remote.worker_s') IS NOT NULL OR json_type(NEW.rest, '$.pre_run.run_s') IS NOT NULL OR json_type(NEW.rest, '$.pre_run.skipped') IS NOT NULL OR json_type(NEW.rest, '$.pre_run.wait_s') IS NOT NULL OR json_type(NEW.rest, '$.pre_run.workers') IS NOT NULL OR json_type(NEW.rest, '$.pre_s') IS NOT NULL OR json_type(NEW.rest, '$.recorded') IS NOT NULL OR json_type(NEW.rest, '$.red_cause.cause') IS NOT NULL OR json_type(NEW.rest, '$.red_cause.rule') IS NOT NULL OR json_type(NEW.rest, '$.red_cause.tests') IS NOT NULL OR json_type(NEW.rest, '$.red_logs') IS NOT NULL OR json_type(NEW.rest, '$.remote_shares') IS NOT NULL OR json_type(NEW.rest, '$.repo') IS NOT NULL OR json_type(NEW.rest, '$.requested') IS NOT NULL OR json_type(NEW.rest, '$.sha') IS NOT NULL OR json_type(NEW.rest, '$.slot_s') IS NOT NULL OR json_type(NEW.rest, '$.slot_wait_by_class.land') IS NOT NULL OR json_type(NEW.rest, '$.slot_wait_by_class.pre') IS NOT NULL OR json_type(NEW.rest, '$.slot_wait_by_class.short') IS NOT NULL OR json_type(NEW.rest, '$.slot_wait_by_class.work') IS NOT NULL OR json_type(NEW.rest, '$.slot_wait_s') IS NOT NULL OR json_type(NEW.rest, '$.stage') IS NOT NULL OR json_type(NEW.rest, '$.started') IS NOT NULL OR json_type(NEW.rest, '$.state') IS NOT NULL OR json_type(NEW.rest, '$.waived') IS NOT NULL OR json_type(NEW.rest, '$.why') IS NOT NULL BEGIN SELECT RAISE(ABORT, 'lands.rest holds a field that has a column'); END;
